 49→  Future<void> _resolveImageDimensions() async {
 50→    final imageUrl = widget.page.imageUrl;
 51→    if (imageUrl == null || imageUrl.isEmpty) {
 52→      return;
 53→    }
 54→
 55→    final completer = Completer<Size>();
 56→    final stream = CachedNetworkImageProvider(
 57→      imageUrl,
 58→      cacheManager: ResilientCacheManager.instance,
 59→    ).resolve(const ImageConfiguration());
 60→    late final ImageStreamListener listener;
 61→    listener = ImageStreamListener(
 62→      (image, _) {
 63→        if (!completer.isCompleted) {
 64→          completer.complete(
 65→            Size(image.image.width.toDouble(), image.image.height.toDouble()),
 66→          );
 67→        }
 68→        stream.removeListener(listener);
 69→      },
 70→      onError: (_, __) {
 71→        if (!completer.isCompleted) {
 72→          completer.complete(Size.zero);
 73→        }
 74→        stream.removeListener(listener);
 75→      },
 76→    );
 77→
 78→    stream.addListener(listener);
 79→    final size = await completer.future;
 80→    if (!mounted) {
 81→      return;
 82→    }
 83→    setState(() {
 84→      _sourceImageSize = size;
 85→    });
 86→  }
 87→
 88→  @override
 89→  Widget build(BuildContext context) {
 90→    final page = widget.page;
 91→    final hasOverlay =
 92→        page.overlay != null && page.overlay!.elements.isNotEmpty;
 93→    final hasFallbackText =
 94→        (page.textContent ?? '').trim().isNotEmpty &&
 95→        (page.imageUrl ?? '').isNotEmpty;
 96→
 97→    return LayoutBuilder(
 98→      builder: (context, constraints) {
 99→        final container = Size(constraints.maxWidth, constraints.maxHeight);
100→        final sourceImageSize = _sourceImageSize;
101→        final imageRect = hasOverlay && sourceImageSize != null
102→            ? computeContainedImageRect(
103→                container: container,
104→                sourceImage: sourceImageSize,
105→              )
106→            : Rect.fromLTWH(0, 0, container.width, container.height);
107→
108→        final activeWordIndex = computeActiveWordIndex(
109→          page.narrationTimestamps,
110→          widget.narrationPosition,
111→        );
112→
113→        return Stack(
114→          fit: StackFit.expand,
