  1→import { useRef, useCallback, useEffect, useState } from 'react';
  2→import { createAudioPlayer, setAudioModeAsync, type AudioPlayer } from 'expo-audio';
  3→
  4→export type AudioPlayerState = {
  5→  isPlaying: boolean;
  6→  positionMs: number;
  7→  durationMs: number;
  8→};
  9→
 10→type UseAudioPlayerReturn = {
 11→  // Narration
 12→  narrationState: AudioPlayerState;
 13→  loadNarration: (uri: string) => Promise<void>;
 14→  playNarration: () => Promise<void>;
 15→  pauseNarration: () => Promise<void>;
 16→  seekNarration: (positionMs: number) => Promise<void>;
 17→  setNarrationVolume: (volume: number) => Promise<void>;
 18→  // Soundscape
 19→  soundscapeState: AudioPlayerState;
 20→  loadSoundscape: (uri: string) => Promise<void>;
 21→  playSoundscape: () => Promise<void>;
 22→  pauseSoundscape: () => Promise<void>;
 23→  setSoundscapeVolume: (volume: number) => Promise<void>;
 24→  // Crossfade
 25→  crossfadeSoundscape: (newUri: string, duration?: number) => Promise<void>;
 26→  fadeOutSoundscape: (duration?: number) => Promise<void>;
 27→  // Cleanup
 28→  cleanup: () => Promise<void>;
 29→};
 30→
 31→export function useAudioPlayer(): UseAudioPlayerReturn {
 32→  const narrationRef = useRef<AudioPlayer | null>(null);
 33→  const soundscapeRef = useRef<AudioPlayer | null>(null);
 34→  const narrationSubRef = useRef<ReturnType<AudioPlayer['addListener']> | null>(null);
 35→  const soundscapeSubRef = useRef<ReturnType<AudioPlayer['addListener']> | null>(null);
 36→  const fadeIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
 37→  // Track the current soundscape volume for fade calculations
 38→  const soundscapeVolumeRef = useRef<number>(0.6);
 39→
 40→  const [narrationState, setNarrationState] = useState<AudioPlayerState>({
 41→    isPlaying: false,
 42→    positionMs: 0,
 43→    durationMs: 0,
 44→  });
 45→
 46→  const [soundscapeState, setSoundscapeState] = useState<AudioPlayerState>({
 47→    isPlaying: false,
 48→    positionMs: 0,
 49→    durationMs: 0,
 50→  });
 51→
 52→  // Configure audio mode for background playback
 53→  useEffect(() => {
 54→    setAudioModeAsync({
 55→      playsInSilentModeIOS: true,
 56→      staysActiveInBackground: true,
 57→      shouldDuckAndroid: true,
 58→    });
 59→  }, []);
 60→
 61→  // Narration controls
 62→  const loadNarration = useCallback(async (uri: string) => {
 63→    // Clean up previous narration player
 64→    if (narrationSubRef.current) {
 65→      narrationSubRef.current.remove();
 66→      narrationSubRef.current = null;
 67→    }
 68→    if (narrationRef.current) {
 69→      narrationRef.current.remove();
 70→      narrationRef.current = null;
 71→    }
 72→
 73→    const player = createAudioPlayer({ uri });
 74→
 75→    // Subscribe to status updates for word-sync (high frequency)
 76→    narrationSubRef.current = player.addListener('playbackStatusUpdate', (status) => {
 77→      setNarrationState({
 78→        isPlaying: status.playing,
 79→        positionMs: (status.currentTime ?? 0) * 1000,
 80→        durationMs: (status.duration ?? 0) * 1000,
 81→      });
 82→    });
 83→
 84→    narrationRef.current = player;
 85→  }, []);
 86→
 87→  const playNarration = useCallback(async () => {
 88→    narrationRef.current?.play();
 89→  }, []);
 90→
 91→  const pauseNarration = useCallback(async () => {
 92→    narrationRef.current?.pause();
 93→  }, []);
 94→
 95→  const seekNarration = useCallback(async (positionMs: number) => {
 96→    narrationRef.current?.seekTo(positionMs / 1000);
 97→  }, []);
 98→
 99→  const setNarrationVolume = useCallback(async (volume: number) => {
100→    if (narrationRef.current) {
101→      narrationRef.current.volume = volume;
102→    }
103→  }, []);
104→
105→  // Soundscape controls
106→  const loadSoundscape = useCallback(async (uri: string) => {
107→    // Clean up previous soundscape player
108→    if (soundscapeSubRef.current) {
109→      soundscapeSubRef.current.remove();
110→      soundscapeSubRef.current = null;
111→    }
112→    if (soundscapeRef.current) {
113→      soundscapeRef.current.remove();
114→      soundscapeRef.current = null;
115→    }
116→
117→    const player = createAudioPlayer({ uri });
118→    player.loop = true;
119→    player.volume = 0.6;
120→    soundscapeVolumeRef.current = 0.6;
121→
122→    soundscapeSubRef.current = player.addListener('playbackStatusUpdate', (status) => {
123→      setSoundscapeState({
124→        isPlaying: status.playing,
125→        positionMs: (status.currentTime ?? 0) * 1000,
126→        durationMs: (status.duration ?? 0) * 1000,
127→      });
128→    });
129→
130→    soundscapeRef.current = player;
131→  }, []);
132→
133→  const playSoundscape = useCallback(async () => {
134→    soundscapeRef.current?.play();
135→  }, []);
136→
137→  const pauseSoundscape = useCallback(async () => {
138→    soundscapeRef.current?.pause();
139→  }, []);
140→
141→  const setSoundscapeVolume = useCallback(async (volume: number) => {
142→    if (soundscapeRef.current) {
143→      soundscapeRef.current.volume = volume;
144→      soundscapeVolumeRef.current = volume;
145→    }
146→  }, []);
147→
148→  // Fade out over duration
149→  const fadeOutSoundscape = useCallback(async (duration: number = 3000) => {
150→    const player = soundscapeRef.current;
151→    if (!player) return;
152→
153→    const startVolume = soundscapeVolumeRef.current;
154→    const steps = 20;
155→    const stepDuration = duration / steps;
156→    const volumeStep = startVolume / steps;
157→    let currentStep = 0;
158→
159→    if (fadeIntervalRef.current) clearInterval(fadeIntervalRef.current);
160→
161→    return new Promise<void>((resolve) => {
162→      fadeIntervalRef.current = setInterval(() => {
163→        currentStep++;
164→        const newVolume = Math.max(0, startVolume - volumeStep * currentStep);
165→        player.volume = newVolume;
166→        soundscapeVolumeRef.current = newVolume;
167→
168→        if (currentStep >= steps) {
169→          if (fadeIntervalRef.current) clearInterval(fadeIntervalRef.current);
170→          player.pause();
171→          resolve();
172→        }
173→      }, stepDuration);
174→    });
175→  }, []);
176→
177→  // Crossfade: fade out current, load new, fade in
178→  const crossfadeSoundscape = useCallback(async (newUri: string, duration: number = 1500) => {
179→    const oldPlayer = soundscapeRef.current;
180→    const oldSub = soundscapeSubRef.current;
181→
182→    // Create new player at volume 0
183→    const newPlayer = createAudioPlayer({ uri: newUri });
184→    newPlayer.loop = true;
185→    newPlayer.volume = 0;
186→
187→    // Subscribe new player to status updates
188→    soundscapeSubRef.current = newPlayer.addListener('playbackStatusUpdate', (status) => {
189→      setSoundscapeState({
190→        isPlaying: status.playing,
191→        positionMs: (status.currentTime ?? 0) * 1000,
192→        durationMs: (status.duration ?? 0) * 1000,
193→      });
194→    });
195→
196→    // Start playing new sound
197→    newPlayer.play();
198→
199→    // Fade out old, fade in new simultaneously
200→    const steps = 15;
201→    const stepDuration = duration / steps;
202→    let currentStep = 0;
203→
204→    if (fadeIntervalRef.current) clearInterval(fadeIntervalRef.current);
205→
206→    return new Promise<void>((resolve) => {
207→      fadeIntervalRef.current = setInterval(() => {
208→        currentStep++;
209→        const progress = currentStep / steps;
210→
211→        // Fade in new
212→        newPlayer.volume = 0.6 * progress;
213→
214→        // Fade out old
215→        if (oldPlayer) {
216→          try {
217→            oldPlayer.volume = 0.6 * (1 - progress);
218→          } catch {
219→            // Old player may already be removed
220→          }
221→        }
222→
223→        if (currentStep >= steps) {
224→          if (fadeIntervalRef.current) clearInterval(fadeIntervalRef.current);
225→
226→          // Cleanup old
227→          if (oldSub) {
228→            try { oldSub.remove(); } catch { /* ignore */ }
229→          }
230→          if (oldPlayer) {
231→            try { oldPlayer.remove(); } catch { /* ignore */ }
232→          }
233→
234→          soundscapeRef.current = newPlayer;
235→          soundscapeVolumeRef.current = 0.6;
236→          resolve();
237→        }
238→      }, stepDuration);
239→    });
240→  }, []);
241→
242→  // Cleanup all audio
243→  const cleanup = useCallback(async () => {
244→    if (fadeIntervalRef.current) clearInterval(fadeIntervalRef.current);
245→
246→    if (narrationSubRef.current) {
247→      try { narrationSubRef.current.remove(); } catch { /* ignore */ }
248→      narrationSubRef.current = null;
249→    }
250→    if (narrationRef.current) {
251→      try { narrationRef.current.remove(); } catch { /* ignore */ }
252→      narrationRef.current = null;
253→    }
254→
255→    if (soundscapeSubRef.current) {
256→      try { soundscapeSubRef.current.remove(); } catch { /* ignore */ }
257→      soundscapeSubRef.current = null;
258→    }
259→    if (soundscapeRef.current) {
260→      try { soundscapeRef.current.remove(); } catch { /* ignore */ }
261→      soundscapeRef.current = null;
262→    }
263→
264→    setNarrationState({ isPlaying: false, positionMs: 0, durationMs: 0 });
265→    setSoundscapeState({ isPlaying: false, positionMs: 0, durationMs: 0 });
266→  }, []);
267→
268→  // Cleanup on unmount
269→  useEffect(() => {
270→    return () => {
271→      cleanup();
272→    };
273→  }, [cleanup]);
274→
275→  return {
276→    narrationState,
277→    loadNarration,
278→    playNarration,
279→    pauseNarration,
280→    seekNarration,
281→    setNarrationVolume,
282→    soundscapeState,
283→    loadSoundscape,
284→    playSoundscape,
285→    pauseSoundscape,
286→    setSoundscapeVolume,
287→    crossfadeSoundscape,
288→    fadeOutSoundscape,
289→    cleanup,
290→  };
291→}
