 49→    }
 50→  }, [isActive, pulse]);
 51→
 52→  const dotStyle = useAnimatedStyle(() => ({
 53→    opacity: pulse.value,
 54→    transform: [{ scale: 0.6 + pulse.value * 0.4 }],
 55→  }));
 56→
 57→  return (
 58→    <Animated.View
 59→      style={[
 60→        {
 61→          position: 'absolute',
 62→          top: 6,
 63→          right: 6,
 64→          width: 6,
 65→          height: 6,
 66→          borderRadius: 3,
 67→          backgroundColor: color,
