 80→  accentColor,
 81→  glowColor,
 82→  isPlaying,
 83→  onPress,
 84→}: {
 85→  icon: string;
 86→  accentColor: string;
 87→  glowColor: string;
 88→  isPlaying: boolean;
 89→  onPress: () => void;
 90→}) {
 91→  const glowOpacity = useSharedValue(0);
 92→
 93→  useEffect(() => {
 94→    glowOpacity.value = withTiming(isPlaying ? 1 : 0, { duration: 300 });
 95→  }, [isPlaying, glowOpacity]);
 96→
 97→  const glowStyle = useAnimatedStyle(() => ({
 98→    opacity: glowOpacity.value,
 99→  }));
100→
101→  return (
102→    <TouchableOpacity
103→      onPress={onPress}
104→      activeOpacity={0.7}
105→      hitSlop={12}
106→      style={styles.iconButtonWrapper}
107→    >
108→      {/* Glow ring behind button when active */}
109→      <Animated.View
110→        style={[
111→          styles.glowRing,
112→          { backgroundColor: glowColor },
113→          glowStyle,
114→        ]}
115→      />
116→      <View
117→        style={[
118→          styles.iconButton,
119→          isPlaying && {
120→            borderColor: accentColor,
121→            borderWidth: 1.5,
122→          },
123→        ]}
124→      >
125→        <Text
126→          style={[
127→            styles.iconText,
128→            { color: isPlaying ? accentColor : 'rgba(255,255,255,0.7)' },
129→          ]}
130→        >
131→          {icon}
132→        </Text>
133→        <PulsingDot color={accentColor} isActive={isPlaying} />
134→      </View>
135→    </TouchableOpacity>
136→  );
137→}
