 5→class BookRepository {
 6→  final SupabaseClient _supabase;
 7→
 8→  const BookRepository(this._supabase);
 9→
10→  Future<List<Book>> getPublishedBooks() async {
11→    final data = await _supabase
12→        .from('books')
13→        .select('id, title, author, cover_url, pages(*, scenes(soundscapes(audio_url, admin_approved)))')
14→        .eq('is_published', true)
15→        .order('inserted_at');
16→
17→    final rows = (data as List<dynamic>).whereType<Map<String, dynamic>>();
18→    return rows.map(Book.fromJson).toList();
19→  }
20→
21→  Future<Book?> getBookById(String bookId) async {
22→    final data = await _supabase
23→        .from('books')
24→        .select('id, title, author, cover_url, pages(*, scenes(soundscapes(audio_url, admin_approved)))')
25→        .eq('id', bookId)
26→        .maybeSingle();
27→
28→    if (data == null) {
29→      return null;
30→    }
31→
32→    return Book.fromJson(Map<String, dynamic>.from(data));
33→  }
34→}
