 21→function StaggerWord({
 22→  word,
 23→  index,
 24→  isHighlighted,
 25→  highlightBg,
 26→  textColor,
 27→  isActive,
 28→  overlayMode,
 29→}: {
 30→  word: string;
 31→  index: number;
 32→  isHighlighted: boolean;
 33→  highlightBg: string;
 34→  textColor: string;
 35→  isActive: boolean;
 36→  overlayMode?: boolean;
 37→}) {
 38→  const progress = useSharedValue(0);
 39→
 40→  useEffect(() => {
 41→    if (isActive) {
 42→      progress.value = 0;
 43→      progress.value = withDelay(
 44→        index * 40,
 45→        withTiming(1, { duration: 300 })
 46→      );
 47→    } else {
 48→      progress.value = 0;
 49→    }
 50→  }, [isActive, index, progress]);
 51→
 52→  const animStyle = useAnimatedStyle(() => ({
 53→    opacity: progress.value,
 54→    transform: [{ translateY: (1 - progress.value) * 12 }],
 55→  }));
 56→
 57→  return (
 58→    <Animated.Text
 59→      style={[
 60→        overlayMode ? styles.overlayWord : styles.word,
 61→        { color: textColor },
 62→        animStyle,
 63→        isHighlighted && { backgroundColor: highlightBg },
 64→      ]}
 65→    >
 66→      {word}{' '}
 67→    </Animated.Text>
 68→  );
 69→}
