 71→export function WordHighlighter({
 72→  text,
 73→  timestamps,
 74→  currentPositionMs,
 75→  isPlaying,
 76→  isActive = true,
 77→  overlayMode = false,
 78→}: Props) {
 79→  const colors = useThemeColors();
 80→
 81→  const activeWordIndex = useMemo(() => {
 82→    if (!isPlaying || !timestamps || timestamps.length === 0) return -1;
 83→
 84→    const currentTime = currentPositionMs / 1000;
 85→    let foundIndex = -1;
 86→
 87→    for (let i = 0; i < timestamps.length; i++) {
 88→      const wordData = timestamps[i];
 89→      const nextWord = timestamps[i + 1];
 90→
 91→      if (currentTime >= wordData.start && currentTime <= wordData.end) {
 92→        foundIndex = i;
 93→        break;
 94→      }
 95→      if (nextWord && currentTime > wordData.end && currentTime < nextWord.start) {
 96→        foundIndex = i;
 97→        break;
 98→      }
 99→      if (!nextWord && currentTime >= wordData.start) {
100→        foundIndex = i;
101→        break;
102→      }
103→      if (currentTime > wordData.end) {
104→        foundIndex = i;
105→      }
106→    }
107→
108→    return foundIndex;
109→  }, [currentPositionMs, timestamps, isPlaying]);
110→
111→  const textColor = overlayMode ? '#ffffff' : colors.readerText;
112→
113→  if (!timestamps || timestamps.length === 0) {
114→    // Split plain text into words for stagger animation
115→    const words = text.split(/\s+/);
116→    return (
117→      <Animated.Text style={[overlayMode ? styles.overlayText : styles.text, { fontFamily: fonts.serif }]}>
118→        {words.map((word, i) => (
119→          <StaggerWord
120→            key={i}
121→            word={word}
122→            index={i}
123→            isHighlighted={false}
124→            highlightBg={colors.readerHighlightBg}
125→            textColor={textColor}
126→            isActive={isActive}
127→            overlayMode={overlayMode}
128→          />
129→        ))}
130→      </Animated.Text>
131→    );
132→  }
133→
134→  return (
135→    <Animated.Text style={[overlayMode ? styles.overlayText : styles.text, { fontFamily: fonts.serif }]}>
136→      {timestamps.map((wordData, index) => (
137→        <StaggerWord
138→          key={index}
139→          word={wordData.word}
140→          index={index}
141→          isHighlighted={index === activeWordIndex && isPlaying}
142→          highlightBg={colors.readerHighlightBg}
143→          textColor={textColor}
144→          isActive={isActive}
145→          overlayMode={overlayMode}
146→        />
147→      ))}
148→    </Animated.Text>
149→  );
150→}

