  1→import React, { useEffect } from 'react';
  2→import { View, Text, TouchableOpacity, StyleSheet } from 'react-native';
  3→import { BlurView } from 'expo-blur';
  4→import Animated, {
  5→  useAnimatedStyle,
  6→  useSharedValue,
  7→  withTiming,
  8→  withRepeat,
  9→  withSequence,
 10→  Easing,
 11→} from 'react-native-reanimated';
 12→import { useSafeAreaInsets } from 'react-native-safe-area-context';
 13→import { fonts } from '@/lib/theme';
 14→
 15→// Accent colors
 16→const NARRATION_COLOR = '#F59E0B'; // Warm amber
 17→const NARRATION_GLOW = 'rgba(245, 158, 11, 0.25)';
 18→const SOUNDSCAPE_COLOR = '#14B8A6'; // Teal
 19→const SOUNDSCAPE_GLOW = 'rgba(20, 184, 166, 0.25)';
 20→
 21→type Props = {
 22→  hasNarration: boolean;
 23→  hasSoundscape: boolean;
 24→  isNarrationPlaying: boolean;
 25→  isSoundscapePlaying: boolean;
 26→  onToggleNarration: () => void;
 27→  onToggleSoundscape: () => void;
 28→  isVisible?: boolean;
 29→};
 30→
 31→/**
 32→ * Pulsing dot indicator that shows when audio is playing.
 33→ */
 34→function PulsingDot({ color, isActive }: { color: string; isActive: boolean }) {
 35→  const pulse = useSharedValue(1);
 36→
 37→  useEffect(() => {
 38→    if (isActive) {
 39→      pulse.value = withRepeat(
 40→        withSequence(
 41→          withTiming(0.4, { duration: 800, easing: Easing.inOut(Easing.ease) }),
 42→          withTiming(1, { duration: 800, easing: Easing.inOut(Easing.ease) })
 43→        ),
 44→        -1,
 45→        true
 46→      );
 47→    } else {
 48→      pulse.value = withTiming(0, { duration: 200 });
 49→    }
 50→  }, [isActive, pulse]);
 51→
 52→  const dotStyle = useAnimatedStyle(() => ({
 53→    opacity: pulse.value,
 54→    transform: [{ scale: 0.6 + pulse.value * 0.4 }],
 55→  }));
 56→
 57→  return (
 58→    <Animated.View
 59→      style={[
 60→        {
 61→          position: 'absolute',
 62→          top: 6,
 63→          right: 6,
 64→          width: 6,
 65→          height: 6,
 66→          borderRadius: 3,
 67→          backgroundColor: color,
 68→        },
 69→        dotStyle,
 70→      ]}
 71→    />
 72→  );
 73→}
 74→
 75→/**
 76→ * A single circular icon button for audio control.
 77→ */
 78→function AudioIconButton({
 79→  icon,
 80→  accentColor,
 81→  glowColor,
 82→  isPlaying,
 83→  onPress,
 84→}: {
 85→  icon: string;
 86→  accentColor: string;
 87→  glowColor: string;
 88→  isPlaying: boolean;
 89→  onPress: () => void;
 90→}) {
 91→  const glowOpacity = useSharedValue(0);
 92→
 93→  useEffect(() => {
 94→    glowOpacity.value = withTiming(isPlaying ? 1 : 0, { duration: 300 });
 95→  }, [isPlaying, glowOpacity]);
 96→
 97→  const glowStyle = useAnimatedStyle(() => ({
 98→    opacity: glowOpacity.value,
 99→  }));
100→
101→  return (
102→    <TouchableOpacity
103→      onPress={onPress}
104→      activeOpacity={0.7}
105→      hitSlop={12}
106→      style={styles.iconButtonWrapper}
107→    >
108→      {/* Glow ring behind button when active */}
109→      <Animated.View
110→        style={[
111→          styles.glowRing,
112→          { backgroundColor: glowColor },
113→          glowStyle,
114→        ]}
115→      />
116→      <View
117→        style={[
118→          styles.iconButton,
119→          isPlaying && {
120→            borderColor: accentColor,
121→            borderWidth: 1.5,
122→          },
123→        ]}
124→      >
125→        <Text
126→          style={[
127→            styles.iconText,
128→            { color: isPlaying ? accentColor : 'rgba(255,255,255,0.7)' },
129→          ]}
130→        >
131→          {icon}
132→        </Text>
133→        <PulsingDot color={accentColor} isActive={isPlaying} />
134→      </View>
135→    </TouchableOpacity>
136→  );
137→}
138→
139→export const AudioControls = React.memo(function AudioControls({
140→  hasNarration,
141→  hasSoundscape,
142→  isNarrationPlaying,
143→  isSoundscapePlaying,
144→  onToggleNarration,
145→  onToggleSoundscape,
146→  isVisible = true,
147→}: Props) {
148→  const insets = useSafeAreaInsets();
149→  const hasAudio = hasNarration || hasSoundscape;
150→  const shouldShow = hasAudio && isVisible;
151→
152→  const containerStyle = useAnimatedStyle(() => ({
153→    opacity: withTiming(shouldShow ? 1 : 0, { duration: 300 }),
154→    transform: [{ translateY: withTiming(shouldShow ? 0 : 16, { duration: 300 }) }],
155→  }));
156→
157→  if (!hasAudio) return null;
158→
159→  return (
160→    <Animated.View
161→      style={[
162→        styles.container,
163→        { bottom: Math.max(28, insets.bottom + 12) },
164→        containerStyle,
165→      ]}
166→      pointerEvents={shouldShow ? 'auto' : 'none'}
167→    >
168→      <BlurView
169→        intensity={35}
170→        tint="dark"
171→        style={styles.pillContainer}
172→      >
173→        <View style={styles.buttonsRow}>
174→          {hasNarration && (
175→            <AudioIconButton
176→              icon={isNarrationPlaying ? '\u23F8' : '\uD83C\uDFA4'}
177→              accentColor={NARRATION_COLOR}
178→              glowColor={NARRATION_GLOW}
179→              isPlaying={isNarrationPlaying}
180→              onPress={onToggleNarration}
181→            />
182→          )}
183→          {hasNarration && hasSoundscape && <View style={styles.divider} />}
184→          {hasSoundscape && (
185→            <AudioIconButton
186→              icon={isSoundscapePlaying ? '\uD83D\uDD0A' : '\uD83C\uDFB5'}
187→              accentColor={SOUNDSCAPE_COLOR}
188→              glowColor={SOUNDSCAPE_GLOW}
189→              isPlaying={isSoundscapePlaying}
190→              onPress={onToggleSoundscape}
191→            />
192→          )}
193→        </View>
194→      </BlurView>
195→    </Animated.View>
196→  );
197→});
198→
199→const styles = StyleSheet.create({
200→  container: {
