215→    borderColor: 'rgba(255,255,255,0.1)',
216→  },
217→  buttonsRow: {
218→    flexDirection: 'row',
219→    alignItems: 'center',
220→    gap: 4,
221→  },
222→  divider: {
223→    width: StyleSheet.hairlineWidth,
224→    height: 24,
225→    backgroundColor: 'rgba(255,255,255,0.12)',
226→    marginHorizontal: 4,
227→  },
228→  iconButtonWrapper: {
229→    position: 'relative',
230→    width: 48,
231→    height: 48,
232→    justifyContent: 'center',
233→    alignItems: 'center',
234→  },
235→  glowRing: {
236→    position: 'absolute',
237→    width: 48,
238→    height: 48,
239→    borderRadius: 24,
240→  },
241→  iconButton: {
242→    width: 44,
243→    height: 44,
244→    borderRadius: 22,
245→    backgroundColor: 'rgba(255,255,255,0.06)',
246→    justifyContent: 'center',
247→    alignItems: 'center',
