  1→import { useRef, useCallback, useEffect, useState } from 'react';
  2→import { createAudioPlayer, setAudioModeAsync, type AudioPlayer } from 'expo-audio';
  3→
  4→export type AudioPlayerState = {
  5→  isPlaying: boolean;
  6→  positionMs: number;
  7→  durationMs: number;
  8→};
  9→
 10→type UseAudioPlayerReturn = {
 11→  // Narration
 12→  narrationState: AudioPlayerState;
 13→  loadNarration: (uri: string) => Promise<void>;
 14→  playNarration: () => Promise<void>;
 15→  pauseNarration: () => Promise<void>;
 16→  seekNarration: (positionMs: number) => Promise<void>;
 17→  setNarrationVolume: (volume: number) => Promise<void>;
 18→  // Soundscape
 19→  soundscapeState: AudioPlayerState;
 20→  loadSoundscape: (uri: string) => Promise<void>;
 21→  playSoundscape: () => Promise<void>;
 22→  pauseSoundscape: () => Promise<void>;
 23→  setSoundscapeVolume: (volume: number) => Promise<void>;
 24→  // Crossfade
 25→  crossfadeSoundscape: (newUri: string, duration?: number) => Promise<void>;
 26→  fadeOutSoundscape: (duration?: number) => Promise<void>;
 27→  // Cleanup
 28→  cleanup: () => Promise<void>;
 29→};
 30→
 31→export function useAudioPlayer(): UseAudioPlayerReturn {
 32→  const narrationRef = useRef<AudioPlayer | null>(null);
 33→  const soundscapeRef = useRef<AudioPlayer | null>(null);
 34→  const narrationSubRef = useRef<ReturnType<AudioPlayer['addListener']> | null>(null);
 35→  const soundscapeSubRef = useRef<ReturnType<AudioPlayer['addListener']> | null>(null);
 36→  const fadeIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
 37→  // Track the current soundscape volume for fade calculations
 38→  const soundscapeVolumeRef = useRef<number>(0.6);
 39→
 40→  const [narrationState, setNarrationState] = useState<AudioPlayerState>({
 41→    isPlaying: false,
 42→    positionMs: 0,
 43→    durationMs: 0,
 44→  });
 45→
 46→  const [soundscapeState, setSoundscapeState] = useState<AudioPlayerState>({
 47→    isPlaying: false,
 48→    positionMs: 0,
 49→    durationMs: 0,
 50→  });
 51→
 52→  // Configure audio mode for background playback
 53→  useEffect(() => {
 54→    setAudioModeAsync({
 55→      playsInSilentModeIOS: true,
 56→      staysActiveInBackground: true,
 57→      shouldDuckAndroid: true,
 58→    });
 59→  }, []);
 60→
 61→  // Narration controls
 62→  const loadNarration = useCallback(async (uri: string) => {
 63→    // Clean up previous narration player
 64→    if (narrationSubRef.current) {
 65→      narrationSubRef.current.remove();
 66→      narrationSubRef.current = null;
 67→    }
 68→    if (narrationRef.current) {
 69→      narrationRef.current.remove();
 70→      narrationRef.current = null;
 71→    }
 72→
 73→    const player = createAudioPlayer({ uri });
 74→
 75→    // Subscribe to status updates for word-sync (high frequency)
 76→    narrationSubRef.current = player.addListener('playbackStatusUpdate', (status) => {
 77→      setNarrationState({
 78→        isPlaying: status.playing,
 79→        positionMs: (status.currentTime ?? 0) * 1000,
 80→        durationMs: (status.duration ?? 0) * 1000,
 81→      });
 82→    });
 83→
 84→    narrationRef.current = player;
 85→  }, []);
 86→
 87→  const playNarration = useCallback(async () => {
 88→    narrationRef.current?.play();
 89→  }, []);
 90→
 91→  const pauseNarration = useCallback(async () => {
 92→    narrationRef.current?.pause();
 93→  }, []);
 94→
 95→  const seekNarration = useCallback(async (positionMs: number) => {
 96→    narrationRef.current?.seekTo(positionMs / 1000);
 97→  }, []);
 98→
 99→  const setNarrationVolume = useCallback(async (volume: number) => {
100→    if (narrationRef.current) {
101→      narrationRef.current.volume = volume;
102→    }
103→  }, []);
104→
105→  // Soundscape controls
106→  const loadSoundscape = useCallback(async (uri: string) => {
107→    // Clean up previous soundscape player
108→    if (soundscapeSubRef.current) {
109→      soundscapeSubRef.current.remove();
110→      soundscapeSubRef.current = null;
111→    }
112→    if (soundscapeRef.current) {
113→      soundscapeRef.current.remove();
